function draw() {
    ctx.clearRect(0, 0, width, height);
    // draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.size, player.size);
    // draw shapes as circles with gradient
    shapes.forEach(s => {
