        s.x + s.size / 2,
        s.y + s.size / 2,
        s.size / 2
      );
      grad.addColorStop(0, '#fff');
      grad.addColorStop(1, s.color);
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(s.x + s.size / 2, s.y + s.size / 2, s.size / 2, 0, Math.PI * 2);
      ctx.fill();
    });
